  /* Mobile: always show download button (no hover needed) */
  @media (max-width: 768px) {
    .pin-card .pin-dlbtn {
      opacity: 1 !important;
      width: 32px !important;
      height: 32px !important;
      top: 8px !important;
      right: 8px !important;
    }
  }

  /* Touch feedback */
  .pin-card:active {
    opacity: 0.92;
  }

  /* Prevent any horizontal overflow */
  .masonry-grid {
    max-width: 100%;
    overflow-x: hidden;
  }

  /* Skeleton pins */
  .pin-skeleton {
    break-inside: avoid;
    margin-bottom: 12px;
    display: block;
    width: 100%;
    box-sizing: border-box;
  }
`;
