// ─── Pinterest CSS — hover/mobile download button visibility + masonry responsive
const imageSearchCSS = `
  /* Desktop: hide download btn by default, show on card hover */
  .pin-card .pin-dlbtn {
    opacity: 0;
  }
  .pin-card:hover .pin-dlbtn {
    opacity: 1;
  }
  .pin-card:hover .pin-overlay {
    opacity: 1 !important;
  }

  /* Slight zoom on hover */
  .pin-card:hover img {
    transform: scale(1.03);
  }

  /* Masonry responsive breakpoints */
  @media (max-width: 1024px) {
    .masonry-grid {
      columns: 3 180px !important;
    }
  }

  @media (max-width: 768px) {
    .masonry-grid {
      columns: 2 140px !important;
      column-gap: 10px !important;
    }
    .pin-card {
      margin-bottom: 10px !important;
      border-radius: 12px !important;
    }
    .pin-card img {
      border-radius: 12px !important;
    }
    .pin-card .pin-overlay {
      border-radius: 12px !important;
    }
  }

  @media (max-width: 480px) {
    .masonry-grid {
      columns: 2 120px !important;
      column-gap: 8px !important;
    }
    .pin-card {
      margin-bottom: 8px !important;
      border-radius: 10px !important;
    }
    .pin-card img {
      border-radius: 10px !important;
    }
  }

  /* Mobile: always show download button (no hover needed) */
  @media (max-width: 768px) {
    .pin-card .pin-dlbtn {
      opacity: 1 !important;
      width: 32px !important;
      height: 32px !important;
      top: 8px !important;
      right: 8px !important;
    }
  }

  /* Touch feedback */
  .pin-card:active {
    opacity: 0.92;
  }

  /* Prevent any horizontal overflow */
  .masonry-grid {
    max-width: 100%;
    overflow-x: hidden;
  }

  /* Skeleton pins */
  .pin-skeleton {
    break-inside: avoid;
    margin-bottom: 12px;
    display: block;
    width: 100%;
    box-sizing: border-box;
  }
`;

